<!-- Client-side Interactive Filter Script -->
<script>
    function copyToClipboard(text, deptLabel) {
      if (navigator.clipboard) {
        navigator.clipboard.writeText(text).then(function() {
          showCopyToast(deptLabel + ' email copied to clipboard!');
        });
      } else {
        var dummy = document.createElement('textarea');
        document.body.appendChild(dummy);
        dummy.value = text;
        dummy.select();
        document.execCommand('copy');
        document.body.removeChild(dummy);
        showCopyToast(deptLabel + ' email copied to clipboard!');
      }
    }

    function showCopyToast(msg) {
      var toast = document.getElementById('copy-toast');
      var toastMsg = document.getElementById('copy-toast-msg');
      if (toast && toastMsg) {
        toastMsg.textContent = msg;
        toast.classList.remove('translate-y-20', 'opacity-0');
        toast.classList.add('translate-y-0', 'opacity-100');
        setTimeout(function() {
          toast.classList.remove('translate-y-0', 'opacity-100');
          toast.classList.add('translate-y-20', 'opacity-0');
        }, 3200);
      }
    }

    function resetSearch() {
      var searchInput = document.getElementById('dept-search-input');
      if (searchInput) {
        searchInput.value = '';
      }
      var clearBtn = document.getElementById('clear-search-btn');
      if (clearBtn) {
        clearBtn.classList.add('hidden');
      }
      var filterButtons = document.querySelectorAll('.dept-filter-btn');
      filterButtons.forEach(function(btn) {
        if (btn.getAttribute('data-filter') === 'all') {
          btn.classList.add('bg-primary', 'text-on-primary');
          btn.classList.remove('bg-surface-container', 'text-on-surface-variant');
        } else {
          btn.classList.remove('bg-primary', 'text-on-primary');
          btn.classList.add('bg-surface-container', 'text-on-surface-variant');
        }
      });
      applyDirectoryFilter('', 'all');
    }

    function applyDirectoryFilter(query, activeFilter) {
      var cards = document.querySelectorAll('[data-dept-card]');
      var visibleCount = 0;
      var cleanQuery = (query || '').toLowerCase().trim();

      cards.forEach(function(card) {
        var cardText = card.textContent.toLowerCase();
        var cardCategory = (card.getAttribute('data-category') || '').toLowerCase();
        
        var matchesSearch = cleanQuery === '' || cardText.indexOf(cleanQuery) !== -1 || cardCategory.indexOf(cleanQuery) !== -1;
        var matchesCategory = activeFilter === 'all' || cardCategory.indexOf(activeFilter.toLowerCase()) !== -1;

        if (matchesSearch && matchesCategory) {
          card.classList.remove('hidden');
          visibleCount++;
        } else {
          card.classList.add('hidden');
        }
      });

      var countEl = document.getElementById('visible-count');
      if (countEl) {
        countEl.textContent = visibleCount;
      }

      var noResults = document.getElementById('no-results-state');
      if (noResults) {
        if (visibleCount === 0) {
          noResults.classList.remove('hidden');
        } else {
          noResults.classList.add('hidden');
        }
      }
    }

    document.addEventListener('DOMContentLoaded', function() {
      var searchInput = document.getElementById('dept-search-input');
      var clearBtn = document.getElementById('clear-search-btn');
      var filterButtons = document.querySelectorAll('.dept-filter-btn');
      var currentFilter = 'all';

      if (searchInput) {
        searchInput.addEventListener('input', function(e) {
          var val = e.target.value;
          if (clearBtn) {
            if (val.length > 0) {
              clearBtn.classList.remove('hidden');
            } else {
              clearBtn.classList.add('hidden');
            }
          }
          applyDirectoryFilter(val, currentFilter);
        });
      }

      if (clearBtn) {
        clearBtn.addEventListener('click', function() {
          if (searchInput) {
            searchInput.value = '';
          }
          clearBtn.classList.add('hidden');
          applyDirectoryFilter('', currentFilter);
        });
      }

      filterButtons.forEach(function(button) {
        button.addEventListener('click', function() {
          var filterVal = button.getAttribute('data-filter');
          currentFilter = filterVal;

          filterButtons.forEach(function(btn) {
            btn.classList.remove('bg-primary', 'text-on-primary');
            btn.classList.add('bg-surface-container', 'text-on-surface-variant');
          });

          button.classList.add('bg-primary', 'text-on-primary');
          button.classList.remove('bg-surface-container', 'text-on-surface-variant');

          var searchVal = searchInput ? searchInput.value : '';
          applyDirectoryFilter(searchVal, currentFilter);
        });
      });
    });
  </script>
